begin;
set local search_path=extensions,public,private;
select no_plan();
insert into auth.sessions(id,user_id) values('98000000-0000-4000-8000-000000000001','10000000-0000-0000-0000-000000000001');
insert into auth.identities(id,user_id,provider,provider_id,identity_data) values('98000000-0000-4000-8000-000000000002','10000000-0000-0000-0000-000000000001','apple','apple-flow-sub','{"sub":"apple-flow-sub"}');
select ok(not has_function_privilege('service_role','public.apple_token_store(uuid,text,text,text)','execute'),'legacy service writer cannot bypass current-session check');
select ok(not has_function_privilege('service_role','public.apple_authorization_start(uuid,text,text)','execute'),'legacy unbound OAuth state cannot be created');
select ok(not has_function_privilege('authenticated','public.apple_authorization_start_bound(uuid,text,text,uuid,text)','execute'),'client cannot choose another account or Apple subject');
select ok(not has_function_privilege('anon','public.apple_custody_context()','execute'),'anonymous cannot read custody context');
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
select set_config('request.jwt.claims','{"session_id":"98000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select is(public.apple_custody_context()->>'subject','apple-flow-sub','authoritative Apple identity comes from auth.identities');
select is(public.apple_custody_context()->>'sessionId','98000000-0000-4000-8000-000000000001','custody binds verified JWT session');
reset role;
select throws_ok($$select public.apple_authorization_start_bound('10000000-0000-0000-0000-000000000002','apple-flow-sub',repeat('a',64),'98000000-0000-4000-8000-000000000001','web')$$,'42501','apple_session_required','session cannot authorize a different account');
select throws_ok($$select public.apple_authorization_start_bound('10000000-0000-0000-0000-000000000001','wrong-sub',repeat('a',64),'98000000-0000-4000-8000-000000000001','web')$$,'42501','apple_identity_mismatch','OAuth state cannot bind a different Apple identity');
select lives_ok($$select public.apple_authorization_start_bound('10000000-0000-0000-0000-000000000001','apple-flow-sub',repeat('a',64),'98000000-0000-4000-8000-000000000001','web')$$,'web authorization starts with current session');
select set_config('test.apple_flow',public.apple_authorization_take(repeat('a',64))::text,true);
select is(current_setting('test.apple_flow')::jsonb->>'returnMode','web','web return choice is taken from stored state');
select is(current_setting('test.apple_flow')::jsonb->>'sessionId','98000000-0000-4000-8000-000000000001','callback receives original session binding');
select is(public.apple_authorization_take(repeat('a',64)),null::jsonb,'consumed OAuth state cannot replay');
select public.apple_authorization_start_bound('10000000-0000-0000-0000-000000000001','apple-flow-sub',repeat('b',64),'98000000-0000-4000-8000-000000000001','native');
update private.apple_authorization_flows set created_at=now()-interval '11 minutes' where state_hash=repeat('b',64);
select is(public.apple_authorization_take(repeat('b',64)),null::jsonb,'expired OAuth state cannot exchange a new code');
select is((select count(*)::integer from private.apple_authorization_flows where state_hash=repeat('b',64)),0,'expired state is consumed permanently');
select public.apple_authorization_start_bound('10000000-0000-0000-0000-000000000001','apple-flow-sub',repeat('c',64),'98000000-0000-4000-8000-000000000001','native');
select lives_ok($$select public.apple_token_store_authorized('10000000-0000-0000-0000-000000000001','apple-flow-sub','is.rummal.app',repeat('x',40),'98000000-0000-4000-8000-000000000001')$$,'authorized native custody persists only under the current session');
update public.profiles set deletion_requested_at=now() where id='10000000-0000-0000-0000-000000000001';
select is(public.apple_authorization_take(repeat('c',64)),null::jsonb,'pending deletion invalidates outstanding web callback');
select throws_ok($$select public.apple_token_store_authorized('10000000-0000-0000-0000-000000000001','apple-flow-sub','is.rummal.app',repeat('x',40),'98000000-0000-4000-8000-000000000001')$$,'42501','apple_session_required','provider response cannot retain a new token after deletion starts');
update public.profiles set deletion_requested_at=null where id='10000000-0000-0000-0000-000000000001';
select public.apple_authorization_start_bound('10000000-0000-0000-0000-000000000001','apple-flow-sub',repeat('d',64),'98000000-0000-4000-8000-000000000001','web');
delete from auth.sessions where id='98000000-0000-4000-8000-000000000001';
select is(public.apple_authorization_take(repeat('d',64)),null::jsonb,'logout deletes outstanding state through session FK');
select throws_ok($$select public.apple_token_store_authorized('10000000-0000-0000-0000-000000000001','apple-flow-sub','is.rummal.app',repeat('x',40),'98000000-0000-4000-8000-000000000001')$$,'42501','apple_session_required','logout between exchange and custody cannot store refreshed credentials');
set local role authenticated;
select throws_ok($$select public.apple_custody_context()$$,'42501','apple_session_required','revoked JWT session cannot request more authorizations');
reset role;
select * from finish();
rollback;
